class Solution {
public long maximumScore(int[][] grid){int n=grid.length;long neg=-1000000000000000L;long[][] dp=new long[n+1][n+1];for(long[] row:dp)Arrays.fill(row,neg);Arrays.fill(dp[0],0);for(int col=0;col<n;col++){long[] prefix=new long[n+1];for(int r=0;r<n;r++)prefix[r+1]=prefix[r]+grid[r][col];long[][] next=new long[n+1][n+1];for(long[] row:next)Arrays.fill(row,neg);for(int b=0;b<=n;b++){long[] pre=new long[n+1],suffix=new long[n+2];long best=neg;for(int a=0;a<=n;a++){best=Math.max(best,dp[a][b]);pre[a]=best;}Arrays.fill(suffix,neg);for(int a=n;a>=0;a--)suffix[a]=Math.max(suffix[a+1],dp[a][b]+Math.max(0,prefix[a]-prefix[b]));for(int c=0;c<(col<n-1?n+1:1);c++)next[b][c]=Math.max(pre[c]+Math.max(0,prefix[c]-prefix[b]),suffix[c+1]);}dp=next;}long ans=0;for(long[] row:dp)ans=Math.max(ans,row[0]);return ans;}
}
